import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] a = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) { a[i] = r.nextLong(); sum += a[i]; }
        long average = sum / n, prefix = 0, low = 0, high = 0;
        // The sum of prefixes can exceed 64 bits: accumulate in chunks into a BigInteger.
        BigInteger total = BigInteger.ZERO;
        long chunk = 0;
        for (int i = 0; i < n; i++) {
            prefix += a[i] - average;
            chunk += prefix;
            if ((i & 1023) == 1023) { total = total.add(BigInteger.valueOf(chunk)); chunk = 0; }
            low = Math.min(low, prefix);
            high = Math.max(high, prefix);
        }
        total = total.add(BigInteger.valueOf(chunk));
        BigInteger nn = BigInteger.valueOf(n);
        BigInteger fwd = total.subtract(nn.multiply(BigInteger.valueOf(low)));
        BigInteger back = nn.multiply(BigInteger.valueOf(high)).subtract(total);
        System.out.println(fwd.min(back));
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

