func main() {
	n := readInt()
	a := make([]int, n)
	sum := 0
	for i := range a {
		a[i] = readInt()
		sum += a[i]
	}
	average := sum / n
	prefix, low, high := 0, 0, 0
	// The sum of prefixes can exceed 64 bits: accumulate in chunks into a big.Int.
	total := new(big.Int)
	chunk := 0
	for i, v := range a {
		prefix += v - average
		chunk += prefix
		if i&1023 == 1023 {
			total.Add(total, big.NewInt(int64(chunk)))
			chunk = 0
		}
		low, high = min(low, prefix), max(high, prefix)
	}
	total.Add(total, big.NewInt(int64(chunk)))
	nn := big.NewInt(int64(n))
	fwd := new(big.Int).Sub(total, new(big.Int).Mul(nn, big.NewInt(int64(low))))
	back := new(big.Int).Sub(new(big.Int).Mul(nn, big.NewInt(int64(high))), total)
	if back.Cmp(fwd) < 0 {
		fwd = back
	}
	fmt.Println(fwd.String())
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
